// ============================================
// VALIDATE STRIPE SIGNATURE
// RFC-025 Section 14.1.4
// ============================================

const crypto = require('crypto');

const input = $input.first().json;
const headers = input.headers || {};
const rawBody = input.body;

// Get stripe-signature header
const sigHeader = headers['stripe-signature'];
if (!sigHeader) {
  return {
    valid: false,
    error: {
      code: 400,
      message: 'Missing stripe-signature header',
      status: 'SIGNATURE_MISSING'
    }
  };
}

// Parse signature header (format: t=timestamp,v1=signature)
const sigParts = {};
for (const part of sigHeader.split(',')) {
  const [key, value] = part.split('=');
  sigParts[key] = value;
}

const timestamp = sigParts.t;
const signature = sigParts.v1;

if (!timestamp || !signature) {
  return {
    valid: false,
    error: {
      code: 400,
      message: 'Invalid stripe-signature format',
      status: 'SIGNATURE_INVALID'
    }
  };
}

// Protection replay attack: event age < 5 minutes
const eventAge = Math.floor(Date.now() / 1000) - parseInt(timestamp);
const maxAge = 300; // 5 minutes

if (eventAge > maxAge) {
  return {
    valid: false,
    error: {
      code: 400,
      message: `Webhook timestamp too old (${eventAge}s > ${maxAge}s)`,
      status: 'REPLAY_ATTACK'
    }
  };
}

// Compute expected signature
const webhookSecret = $env.STRIPE_WEBHOOK_SECRET;
if (!webhookSecret) {
  return {
    valid: false,
    error: {
      code: 500,
      message: 'STRIPE_WEBHOOK_SECRET not configured',
      status: 'CONFIG_ERROR'
    }
  };
}

// Stripe signs: timestamp.payload
const payload = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
const signedPayload = `${timestamp}.${payload}`;

const expectedSignature = crypto
  .createHmac('sha256', webhookSecret)
  .update(signedPayload, 'utf8')
  .digest('hex');

// Compare signatures (timing-safe)
const signaturesMatch = crypto.timingSafeEqual(
  Buffer.from(signature, 'hex'),
  Buffer.from(expectedSignature, 'hex')
);

if (!signaturesMatch) {
  return {
    valid: false,
    error: {
      code: 401,
      message: 'Invalid webhook signature',
      status: 'SIGNATURE_MISMATCH'
    }
  };
}

// Parse event
let event;
try {
  event = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
} catch (e) {
  return {
    valid: false,
    error: {
      code: 400,
      message: 'Invalid JSON payload',
      status: 'INVALID_JSON'
    }
  };
}

// Signature valid!
return {
  valid: true,
  event_id: event.id,
  event_type: event.type,
  event_created: event.created,
  event: event,
  timestamp: new Date().toISOString()
};

// ============================================
// CHECK LOCK AND PREPARE FOR IDEMPOTENCE CHECK
// ============================================

const redisResult = $input.first().json;
const validationData = $('Validate Signature').first().json;

// If lock exists, another process is handling this event
if (redisResult && redisResult.value) {
  return {
    locked: true,
    event_id: validationData.event_id,
    message: 'Event is being processed by another worker'
  };
}

// No lock, proceed
return {
  locked: false,
  event_id: validationData.event_id,
  event_type: validationData.event_type,
  event: validationData.event,
  timestamp: validationData.timestamp
};

// ============================================
// CHECK IDEMPOTENCE RESULT
// ============================================

const dbResult = $input.first().json;
const lockData = $('Check Lock Result').first().json;

// If event already processed, return cached result
if (dbResult && dbResult.length > 0) {
  const existing = Array.isArray(dbResult) ? dbResult[0] : dbResult;
  return {
    already_processed: true,
    event_id: lockData.event_id,
    processed_at: existing.processed_at,
    cached_result: existing.result
  };
}

// Event not processed yet, continue
return {
  already_processed: false,
  event_id: lockData.event_id,
  event_type: lockData.event_type,
  event: lockData.event,
  timestamp: lockData.timestamp
};

// ============================================
// ROUTE EVENT TO HANDLER
// ============================================

const data = $input.first().json;
const eventType = data.event_type;
const event = data.event;

// Log event (sans données sensibles)
console.log(`Processing Stripe event: ${data.event_id} (${eventType})`);

// Préparer les données pour le routing
const subscription = event.data?.object || {};
const customer_id = subscription.customer || event.data?.object?.customer;

return {
  event_id: data.event_id,
  event_type: eventType,
  event_created: event.created,
  timestamp: data.timestamp,
  customer_id: customer_id,
  subscription_id: subscription.id || null,
  subscription_status: subscription.status || null,
  event_data: event.data?.object || {},
  // Flag pour le routing
  route: {
    is_subscription_updated: eventType === 'customer.subscription.updated',
    is_subscription_deleted: eventType === 'customer.subscription.deleted',
    is_payment_succeeded: eventType === 'invoice.payment_succeeded',
    is_payment_failed: eventType === 'invoice.payment_failed',
    is_payment_intent: eventType === 'payment_intent.succeeded',
    is_checkout_completed: eventType === 'checkout.session.completed'
  }
};

// ============================================
// UNHANDLED EVENT TYPE
// ============================================

const data = $input.first().json;

console.log(`Unhandled Stripe event type: ${data.event_type}`);

return {
  handled: false,
  event_id: data.event_id,
  event_type: data.event_type,
  message: `Event type '${data.event_type}' not handled`
};

// ============================================
// MERGE HANDLER RESULTS
// ============================================

// Get data from the routing path that was taken
const items = $input.all();
const result = items[0]?.json || {};

// Get original event data
const routeData = $('Route Event').first().json;

return {
  event_id: routeData.event_id,
  event_type: routeData.event_type,
  handled: result.handled !== false,
  result: result,
  timestamp: new Date().toISOString()
};
